void test_sample(inout NearestData nearest, Material material, vec4 sample_distance_normal)
{
    if (sample_distance_normal.x < nearest.dist&& sample_distance_normal.x>0.)
    {
        nearest.dist = sample_distance_normal.x;
        nearest.material = material;
        nearest.normal = sample_distance_normal.yzw;
    }
}


vec4 sphIntersect( in vec3 ro, in vec3 rd, in vec3 ce, float ra )
{
    vec3 oc = ro - ce;
    float b = dot( oc, rd );
    float c = dot( oc, oc ) - ra*ra;
    float h = b*b - c;
    if( h<0.0 ) return vec4(-1.0); // no intersection
    h = sqrt( h );
    vec3 p = ro + (-b-h) * rd; // where t is the first value in the returned vec2
    vec3 normal = normalize(p - ce);

    return vec4( -b-h, normal );
}


