vec3 c(Material mat, vec3 normal, vec3 lightcol, vec3 lightdir){
    vec3 diffuseColor = mat.d * mat.c * lightcol * max(0., dot(normal, -lightdir));
    vec3 viewDir = -lightdir;
    vec3 reflectionDir = reflect(-viewDir, normal);
    vec3 specularColor = mat.r * lightcol * pow(max(0., dot(reflectionDir, -lightdir)), 32.0);
    return diffuseColor + specularColor;
}



vec3 ray_march(vec3 pos, vec3 viewDir, int it) {

    vec3 ecolor = vec3(1.);
    float ref = 1.;

    for(int i=0; i<it; i++){
        NearestData nearest;
        nearest.dist = 1e5;
        c(pos, viewDir, nearest);
        // break;
        if(nearest.dist == 1e5) break;

        if(nearest.material.e>0.01f){
            ecolor*=(nearest.material.c)*nearest.material.e;
            break;
        }
        //ecolor += c(nearest.material, nearest.normal, vec3(1.0), lightDir) * ref;




        float d = nearest.material.d;
        float r = nearest.material.r;

        vec3 reflectedDir=reflect(viewDir, nearest.normal);

        if ( rand(iTime)<d/(d+r)){

            float diffuseStrength = nearest.material.d;  
            vec3 rv3 = rand3(iTime)-vec3(0.5);
            vec3 nordv3 = normalize(cross(rv3, nearest.normal));


            reflectedDir  = reflect(viewDir, nearest.normal+nordv3*length(nearest.normal)*0.5f);

             ecolor *=.5f;

            if(nearest.material.d>0.01f){
                vec3 diffuseColor =  nearest.material.d * normalize(nearest.material.c)  * max(0., dot(nearest.normal, -reflectedDir));
                ecolor+=diffuseColor*ecolor;
            }
        }
        else{

            ecolor *= r;

        }

        pos += viewDir * nearest.dist;

        viewDir = reflectedDir;
    }
    return ecolor;
}

mat3 camera(vec3 dir) {
	vec3 cd = normalize(dir); // camera direction
	vec3 cr = normalize(cross(vec3(0, 0, 1), cd)); // camera right
	vec3 cu = normalize(cross(cd, cr)); // camera up

	return mat3(cr, cu, cd);
}
